import bpy,numpy as np,json,pathlib
p=pathlib.Path(bpy.data.filepath).parent;d=np.load(p/'mesh-data.npz');obs=[o for o in bpy.context.scene.objects if o.type=='MESH' and not o.hide_render];o=obs[0];v=np.array([tuple(x.co) for x in o.data.vertices]);f=np.array([tuple(x.vertices) for x in o.data.polygons]);r={'one_visible_mesh':len(obs)==1,'vertices_equal':bool(np.allclose(v,d['vertices'],rtol=0,atol=1e-5)),'faces_equal':bool(np.array_equal(f,d['faces'])),'no_external_images':not any(i.source != 'VIEWER' for i in bpy.data.images),'no_text_blocks':len(bpy.data.texts)==0,'hidden_editable_components':len([o for o in bpy.context.scene.objects if o.type=='MESH' and o.hide_render])};r['passed']=all(r[k] for k in ['one_visible_mesh','vertices_equal','faces_equal','no_external_images','no_text_blocks']);(p/'BLEND-QA.json').write_text(json.dumps(r,indent=2));print(r);assert r['passed']
